import"./modulepreload-polyfill-Dezn_h7o.js";/* empty css               */import"./proteger-pagina-CCLhLS-N.js";import{t as e}from"./config-DPSuE5lU.js";document.querySelector(`#login-form`).addEventListener(`submit`,async t=>{t.preventDefault();let n=document.querySelector(`#email`).value,r=document.querySelector(`#password`).value;try{let t=await fetch(`${e}/login`,{method:`POST`,headers:{"Content-Type":`application/json`},body:JSON.stringify({email:n,senha:r})});if(t.ok){let e=await t.json();alert(`Login realizado com sucesso!`),localStorage.setItem(`token`,e.token),window.location.href=`/pages/inicio.html`}else{let e=await t.json();alert(`Erro: ${e.message}`)}}catch(e){console.error(`Erro ao enviar a requisição:`,e),alert(`Erro ao conectar ao servidor.`)}});